with RecursiveUserScores as (
    select
        u.Id as UserId,
        u.DisplayName,
        u.Reputation,
        u.CreationDate,
        sum(case when p.PostTypeId = 1 then p.Score else 0 end) as QuestionScore,
        sum(case when p.PostTypeId = 2 then p.Score else 0 end) as AnswerScore,
        count(p.Id) filter(where p.PostTypeId in (1,2)) as TotalPosts
    from Users u
    left join Posts p on u.Id = p.OwnerUserId
    group by u.Id, u.DisplayName, u.Reputation, u.CreationDate

    union all

    select
        ru.UserId,
        ru.DisplayName,
        ru.Reputation + cast(row_number() over (partition by ru.UserId order by ru.TotalPosts desc) as int),
        ru.CreationDate,
        ru.QuestionScore,
        ru.AnswerScore,
        ru.TotalPosts
    from RecursiveUserScores ru
    where ru.Reputation < 1000
),
BadgesAgg as (
    select
        UserId,
        count(*) FILTER (where Class = 1) as GoldBadges,
        count(*) FILTER (where Class = 2) as SilverBadges,
        count(*) FILTER (where Class = 3) as BronzeBadges,
