with RecursiveTotals as (
  select
    u.Id as UserId,
    u.DisplayName,
    u.Reputation,
    coalesce(sum(case when p.PostTypeId = 1 then 1 else 0 end),0) as QuestionCount,
    coalesce(sum(case when p.PostTypeId = 2 then 1 else 0 end),0) as AnswerCount,
    0 as Level
  from Users u
  left join Posts p on p.OwnerUserId = u.Id
  group by u.Id, u.DisplayName, u.Reputation
union all
  select
    rt.UserId,
    rt.DisplayName,
    rt.Reputation + 10,
    rt.QuestionCount,
    rt.AnswerCount,
    rt.Level + 1
  from RecursiveTotals rt
  where rt.Level < 2 and rt.Reputation < 10000
), PostStats AS (
  select
    p.Id,
