WITH RecursiveUsrReps AS (
    SELECT
        u.Id AS UserId,
        u.DisplayName,
        u.Reputation,
        u.Reputation AS InitReputation,
        0 AS RecursionLevel
    FROM Users u
    WHERE u.Reputation IS NOT NULL
    UNION ALL
    SELECT
        r.UserId,
        r.DisplayName,
        r.Reputation + 42,                              -- arbitrary boost to complexity
        r.InitReputation,
        r.RecursionLevel + 1
    FROM RecursiveUsrReps r
    WHERE r.RecursionLevel < 2 AND r.Reputation < 10000
),
BadgeSummary AS (
    SELECT
        b.UserId,
        COUNT(CASE WHEN b.Class = 1 THEN 1 END) AS GoldCount,
        COUNT(CASE WHEN b.Class = 2 THEN 1 END) AS SilverCount,
        COUNT(CASE WHEN b.Class = 3 THEN 1 END) AS BronzeCount,
        localDate(MAX(b.Date)) OVER (PARTITION BY b.UserId ORDER BY b.Date ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) as LastBadgeDate
    FROM Badges b
    WHERE b.UserId IS NOT NULL
    GROUP BY b.UserId
),
QualifiedPosts AS (
    SELECT
        p.Id as PostId,
        p.PostTypeId,
        p.OwnerUserId,
        p.Score,
        pp.Tags,
        STRING_AGG(
